import React, { useEffect, useState } from "react";

export default function ReferralHistoryTable() {
  const [referrals, setReferrals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchReferralHistory = async () => {
      setLoading(true);
      setError(null);

      const token = localStorage.getItem("authToken"); // Login token
      const baseUrl = process.env.REACT_APP_API_BASE_URL?.trim() || "http://192.168.1.170:8080";

      try {
        const res = await fetch(`${baseUrl}/api/bonus-history/all-referrals`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (!res.ok) throw new Error("Failed to fetch referral history");

        const data = await res.json();
        setReferrals(data);
      } catch (err) {
        console.error("Error fetching referrals:", err);
        setError(err.message || "Something went wrong");
      } finally {
        setLoading(false);
      }
    };

    fetchReferralHistory();
  }, []);

  if (loading) return <p className="text-center text-gray-500">Loading referral history...</p>;
  if (error) return <p className="text-center text-red-500">{error}</p>;

  return (
    <div className="p-6">
      <h2 className="text-xl font-bold mb-4 text-gray-800">Referral Bonus History</h2>
      <div className="overflow-x-auto shadow rounded-lg">
        <table className="min-w-full border border-gray-200 bg-white rounded-lg">
          <thead className="bg-gray-100">
            <tr>
              <th className="px-4 py-2 border">Type</th>
              <th className="px-4 py-2 border">Amount</th>
              <th className="px-4 py-2 border">Referrer (SourceGameId)</th>
              <th className="px-4 py-2 border">User (UserGameId)</th>
              <th className="px-4 py-2 border">Created At</th>
            </tr>
          </thead>
          <tbody>
            {referrals.length > 0 ? (
              referrals.map((ref, index) => (
                <tr key={index} className="hover:bg-gray-50">
                  <td className="px-4 py-2 border text-center">{ref.type}</td>
                  <td className="px-4 py-2 border text-center">{ref.amount}</td>
                  <td className="px-4 py-2 border text-center">{ref.sourceGameId}</td>
                  <td className="px-4 py-2 border text-center">{ref.userGameId}</td>
                  <td className="px-4 py-2 border text-center">
                    {new Date(ref.createdAt).toLocaleString()}
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="5" className="px-4 py-4 text-center text-gray-500 border">
                  No referral history found
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
